{{ (function(){
  var rivit = (haeAamukatsaus.data || []);
  var esc = function(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); };
  var paivat = ['sunnuntai','maanantai','tiistai','keskiviikko','torstai','perjantai','lauantai'];
  var otsikkoPvm = paivat[moment().day()] + ' ' + moment().format('D.M.YYYY') + ' · klo ' + moment().format('HH:mm');
  var varit = {'Myöhässä':'#DC2626','Valmistuu tänään':'#1D4ED8','Valmistuu huomenna':'#60A5FA','Odottaa vastaustamme':'#B45309','Uusi viesti suljettuun työhön':'#B4232A','Tarjous lähetetty, ei vastausta':'#7C3AED','Ei vastuuhenkilöä':'#9CA3AF','Valmis, laskuttamatta':'#059669','Tilaus ilman hintaa tai päivää':'#9CA3AF'};
  var ryhmat = {}; var jarjestys = [];
  rivit.forEach(function(r){
    if (!ryhmat[r.ryhma]) { ryhmat[r.ryhma] = { nimi: r.ryhma, jarj: r.ryhma_jarjestys, kiire: r.kiireellisyys, rivit: [] }; jarjestys.push(r.ryhma); }
    var g = ryhmat[r.ryhma]; g.rivit.push(r); if (r.kiireellisyys < g.kiire) { g.kiire = r.kiireellisyys; }
  });
  var lista = jarjestys.map(function(k){ return ryhmat[k]; }).sort(function(a,b){ return a.jarj - b.jarj; });
  var luku = function(n){ return ryhmat[n] ? ryhmat[n].rivit.length : 0; };
  var myohassa = luku('Myöhässä'), tanaan = luku('Valmistuu tänään'), odottaa = luku('Odottaa vastaustamme'), viestit = luku('Uusi viesti suljettuun työhön');
  var tile = function(nimi, arvo, kuuma){
    return '<div class="tile"><div class="lbl">' + nimi + '</div><div class="val' + (arvo > 0 && kuuma ? ' hot' : (arvo > 0 ? ' mid' : ' zero')) + '">' + arvo + '</div></div>';
  };
  var kortti = function(r){
    var vari = varit[r.ryhma] || '#9CA3AF';
    return '<div class="card" style="border-left-color:' + vari + '" data-id="' + esc(r.id) + '">' +
      '<div class="tp">' + esc(r.tp_numero) + '</div>' +
      '<div class="txt"><div class="t">' + esc(r.otsikko) + '</div><div class="s">' + esc(r.lisatieto) + '</div></div>' +
      '<div class="nuoli">›</div></div>';
  };
  var kiireelliset = lista.filter(function(g){ return g.kiire <= 2; });
  var muut = lista.filter(function(g){ return g.kiire > 2; });
  var osat = [];
  if (myohassa > 0) { osat.push(myohassa + ' myöhässä'); }
  if (tanaan > 0) { osat.push(tanaan + ' valmistuu tänään'); }
  if (odottaa > 0) { osat.push(odottaa + ' odottaa vastaustamme'); }
  if (viestit > 0) { osat.push(viestit + ' uutta viestiä suljettuun työhön'); }
  var kiireLkm = kiireelliset.reduce(function(s,g){ return s + g.rivit.length; }, 0);
  var tilanne;
  if (rivit.length === 0) { tilanne = 'Ei huomiota vaativia töitä. Hyvää päivää!'; }
  else if (osat.length === 0) { tilanne = 'Mikään ei ole kiireellistä tänään. Alla olevat ovat siivottavia asioita, kun ehdit.'; }
  else { tilanne = 'Tänään huomiota vaatii ' + kiireLkm + (kiireLkm === 1 ? ' työ' : ' työtä') + ': ' + osat.join(', ') + '.'; }
  var html = '';
  html += '<div class="head"><div><h1>Raportti</h1><div class="pvm">' + otsikkoPvm + '</div></div>';
  html += '<div class="tiles">' + tile('Myöhässä', myohassa, true) + tile('Tänään', tanaan, true) + tile('Odottaa meitä', odottaa, true) + tile('Uusia viestejä', viestit, true) + '</div></div>';
  html += '<div class="tilanne">' + esc(tilanne) + '</div>';
  kiireelliset.forEach(function(g, gi){
    var eka = g.rivit.slice(0, 6), loput = g.rivit.slice(6);
    html += '<div class="sec"><h2>' + esc(g.nimi) + ' <span class="n">' + g.rivit.length + '</span></h2>';
    html += eka.map(kortti).join('');
    if (loput.length) {
      html += '<div class="piilo" id="k' + gi + '">' + loput.map(kortti).join('') + '</div>';
      html += '<div class="chip lisaa" data-avaa="k' + gi + '">Näytä loput ' + loput.length + '</div>';
    }
    html += '</div>';
  });
  if (muut.length) {
    html += '<div class="sec"><h2>Muut huomiot</h2><div class="chips">';
    html += muut.map(function(g, i){ return '<div class="chip" data-avaa="m' + i + '">' + esc(g.nimi) + ' <b>' + g.rivit.length + '</b></div>'; }).join('');
    html += '</div>';
    html += muut.map(function(g, i){ return '<div class="piilo" id="m' + i + '">' + g.rivit.map(kortti).join('') + '</div>'; }).join('');
    html += '</div>';
  }
  if (rivit.length === 0) { html += '<div class="tyhja">Ei mitään kiireellistä. Työjono on ajan tasalla.</div>'; }
  else { html += '<div class="vihje">Klikkaa työtä avataksesi työkortin.</div>'; }
  var css = 'html,body{margin:0;padding:0;height:100%;overflow-y:auto;background:#fff;font-family:-apple-system,Segoe UI,Roboto,Helvetica,sans-serif;color:#111827}'
    + '.wrap{padding:4px 2px 18px}'
    + '.head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}'
    + 'h1{font-size:20px;margin:0;color:#B4232A;letter-spacing:-.01em}'
    + '.pvm{font-size:12px;color:#6B7280;margin-top:2px;text-transform:capitalize}'
    + '.tiles{display:flex;gap:8px}'
    + '.tile{min-width:92px;border:1px solid #E5E7EB;border-radius:10px;padding:6px 12px 8px;text-align:center;background:#FCFCFD}'
    + '.lbl{font-size:10px;text-transform:uppercase;letter-spacing:.05em;color:#6B7280}'
    + '.val{font-size:24px;font-weight:700;line-height:1.2}'
    + '.val.hot{color:#B4232A}.val.mid{color:#1D4ED8}.val.zero{color:#D1D5DB}'
    + '.tilanne{margin:14px 0 4px;font-size:14px;line-height:1.5;color:#374151;background:#F9FAFB;border:1px solid #F1F2F4;border-radius:8px;padding:10px 12px}'
    + '.sec{margin-top:16px}'
    + 'h2{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#6B7280;margin:0 0 8px;font-weight:700}'
    + 'h2 .n{display:inline-block;background:#F3F4F6;border-radius:9999px;padding:1px 7px;margin-left:4px;color:#374151}'
    + '.card{display:flex;align-items:center;gap:10px;border:1px solid #E5E7EB;border-left:4px solid #9CA3AF;border-radius:8px;padding:8px 10px;margin-bottom:6px;cursor:pointer;background:#fff}'
    + '.card:hover{background:#F9FAFB;border-color:#D1D5DB}'
    + '.tp{font-size:12px;font-weight:700;color:#111827;white-space:nowrap}'
    + '.txt{flex:1;min-width:0}'
    + '.t{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}'
    + '.s{font-size:12px;color:#6B7280;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:1px}'
    + '.nuoli{color:#C7CBD1;font-size:18px;line-height:1}'
    + '.chips{display:flex;flex-wrap:wrap;gap:6px}'
    + '.chip{font-size:12px;background:#F3F4F6;border:1px solid #E5E7EB;border-radius:9999px;padding:5px 11px;cursor:pointer;color:#374151}'
    + '.chip:hover{background:#E5E7EB}.chip b{color:#111827}'
    + '.piilo{display:none;margin-top:8px}.lisaa{display:inline-block;margin-top:2px}'
    + '.vihje{margin-top:14px;font-size:11px;color:#9CA3AF}'
    + '.tyhja{margin-top:16px;font-size:14px;color:#6B7280}';
  var js = 'document.addEventListener("click",function(e){'
    + 'var chip=e.target.closest(".chip");'
    + 'if(chip){var el=document.getElementById(chip.getAttribute("data-avaa"));if(el){el.style.display=(el.style.display==="block"?"none":"block");}return;}'
    + 'var k=e.target.closest(".card");if(k){parent.postMessage("tyo:"+k.getAttribute("data-id"),"*");}});';
  return '<!doctype html><html><head><meta charset="utf-8"><style>' + css + '</style></head><body><div class="wrap">' + html + '</div><script>' + js + '<\/script></body></html>';
})() }}
